    v_silhouetteNormalView = czm_normal * a_silhouetteNormal;
    v_faceNormalAView = czm_normal * a_faceNormalA;
    v_faceNormalBView = czm_normal * a_faceNormalB;
    v_edgeOffset = a_edgeOffset;

